#!/usr/bin/env bash
# Frame-timing run (profile mode, emulator, live seeded server) -> ../PERF-RESULTS.md (generated; do not edit).
#   integration_test/run_perf.sh
APP="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SERVER="$(cd "$APP/../keysthetic-server" && pwd)"
FLUTTER=/opt/homebrew/share/flutter/bin/flutter
DART=/opt/homebrew/share/flutter/bin/dart
ADB=/opt/homebrew/share/android-commandlinetools/platform-tools/adb
DEVICE=emulator-5554
OUT="$APP/PERF-RESULTS.md"
TMP="$(mktemp -d)"; RAW="$TMP/raw.log"; : > "$RAW"

stop_server() { pkill -f bin/server.dart 2>/dev/null; sleep 1; }
trap stop_server EXIT

"$ADB" devices | grep -q "^$DEVICE[[:space:]]*device" || { echo "Emulator $DEVICE is not running" >&2; exit 2; }
stop_server
(cd "$SERVER" && "$DART" run bin/seed.dart) 2>&1 | tee -a "$RAW"
(cd "$SERVER" && nohup "$DART" run bin/server.dart > "$TMP/server.log" 2>&1 &)
for _ in $(seq 1 60); do curl -s -m 1 localhost:8080/health 2>/dev/null | grep -q '"ok":true' && break; sleep 1; done
curl -s -m 2 localhost:8080/health | grep -q '"ok":true' || { echo "server did not start" >&2; exit 2; }

rm -rf "$APP/build/perf"
START=$(date +%s)
(cd "$APP" && "$FLUTTER" drive --profile --no-dds --driver=test_driver/perf_driver.dart --target=integration_test/perf_test.dart -d "$DEVICE") 2>&1 | tee -a "$RAW"
STATUS=${PIPESTATUS[0]}
SECS=$(( $(date +%s) - START ))

MODEL=$("$ADB" -s "$DEVICE" shell getprop ro.product.model | tr -d '\r')
ANDROID=$("$ADB" -s "$DEVICE" shell getprop ro.build.version.release | tr -d '\r')
commit() { local h d; h=$(git -C "$1" rev-parse --short HEAD 2>/dev/null || echo unknown); d=$(git -C "$1" status --porcelain --untracked-files=no | wc -l | tr -d ' '); [ "$d" != "0" ] && h="$h (+$d modified tracked files)"; echo "$h"; }
{
  echo "# Keysthetic frame-timing results"
  echo
  echo "_Generated by \`integration_test/run_perf.sh\`. Do not edit by hand._"
  echo
  echo "**Read this first: these numbers come from an Android EMULATOR ($MODEL, Android $ANDROID) running on a Mac, not a phone.** The emulator's GPU path is software or host-translated, so raster times are indicative only and not comparable to a real device. Build times (Dart UI thread) are more representative. Profile mode, live seeded server (fake data), single run, so treat small differences as noise."
  echo
  echo "- Date: $(date '+%Y-%m-%d %H:%M:%S %z')"
  echo "- Command: \`flutter drive --profile --no-dds --driver=test_driver/perf_driver.dart --target=integration_test/perf_test.dart -d $DEVICE\` (exit $STATUS, ${SECS}s)"
  echo "- App commit: $(commit "$APP"); server commit: $(commit "$SERVER")"
  echo "- Frame budget: 16.67 ms (60 Hz). \"Missed\" = frames over budget. Each row is one \`watchPerformance\` window; navigation inside a window is included."
  echo
  echo "## Summary"
  echo
  if [ -f "$APP/build/perf/table.md" ]; then cat "$APP/build/perf/table.md"; else echo "_No data was reported (the run failed; see the raw output)._"; fi
  echo
  echo "## Raw summaries (JSON from the binding)"
  echo
  echo '```json'
  [ -f "$APP/build/perf/summary.json" ] && cat "$APP/build/perf/summary.json"
  echo '```'
  echo
  echo "## Raw output"
  echo
  echo '```'
  cat "$RAW"
  echo '```'
} > "$OUT"
echo "Wrote $OUT"
exit "$STATUS"
